CREATE OR REPLACE FUNCTION public.aka_agent_staff_runtime_scope(p_staff_id bigint, p_lock text)
 RETURNS SETOF aka_agent_staff_runtime_profile
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
